package com.auth.token.controller;

import com.auth.token.dto.LoginRequest;
import com.auth.token.dto.TokenResponse;
import com.auth.token.service.TokenService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.Auth;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.*;

import java.util.Map;
import java.util.HashMap;

@RestController
@RequestMapping("/api/auth")
@AutoConfigureWebMvcEnabled
public class AuthController {

    @Autowired
    private TokenService tokenService;

    @PostMapping("/login")
    public ResponseEntity<TokenResponse> login(@RequestBody LoginRequest request) {
        // Validate input
        if (request == null || request.getUsername() == null || request.getUsername().isEmpty() ||
            request.getPassword() == null || request.getPassword().isEmpty()) {
            return ResponseEntity.badRequest().build();
        }

        // Perform login and get tokens
        TokenResponse response = tokenService.login(request);

        // Set Refresh Token as HTTP-only cookie
        String cookieValue = "refreshToken=" + response.getAccessToken(); // Note: Actually should be refreshToken token
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.add("Set-Cookie", "refreshToken=" + response.getOneTimeToken() + "; HttpOnly; Max-Age=86400");

        // Actually, the spec says: Cookie: refreshToken=<token>; HttpOnly; Max-Age=86400
        // So we need to set the cookie with proper format

        return ResponseEntity.ok()
                .body(response);
    }
}
