    public ResponseEntity<TokenResponse> renew(@RequestParam Map<String, String> requestMap) {
        // Get refresh token from cookie or header
        String refreshTokenCookie = requestMap.get("refreshTokenCookie");
        String refreshTokenHeader = requestMap.get("refreshTokenHeader");

        // Cookie takes precedence if present
        String refreshToken = refreshTokenCookie != null && !refreshTokenCookie.isEmpty() 
                ? refreshTokenCookie 
                : refreshTokenHeader != null && !refreshTokenHeader.isEmpty() 
                        ? refreshTokenHeader 
                        : null;

        if (refreshToken == null || refreshToken.isEmpty()) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(new TokenResponse());
        }

        // Perform token renewal
        TokenResponse renewedResponse = tokenService.renewRefreshToken(refreshToken);

        // Set new refresh token as cookie
        String newRefreshTokenCookieValue = "refreshToken=" + renewedResponse.getAccessToken();
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.add("Set-Cookie", "refreshToken=" + newRefreshTokenCookieValue + "; HttpOnly; Max-Age=86400");

        return ResponseEntity.ok()
                .contentType(MediaType.APPLICATION_JSON)
                .body(renewedResponse);
    }

    @PostMapping("/logout")
    public ResponseEntity<Map<String, Object>> logout(@RequestHeader("Authorization") String authorizationHeader) {
        // Validate access token from header
        if (authorizationHeader == null || !authorizationHeader.startsWith("Bearer ")) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(Map.of("message", "Invalid authorization header"));
        }

