        if (auth == null || !auth.isAuthenticated()) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(Map.of("message", "Unauthorized"));
        }

        // Get user ID from auth
        String userId = auth.getName(); // Assuming username is stored as user name

        // Invalidate all tokens for this user
        // Note: We need to find all tokens for this user and mark them as revoked
        // Then delete them from database

        // Return success response
        return ResponseEntity.ok(Map.of("message", "Logged out successfully"));
    }

    @PostMapping("/validate-token")
    public ResponseEntity<Map<String, Object>> validateToken(@RequestBody Map<String, Object> request) {
        String token = null;

        // Extract token from request parameter
        if (request.containsKey("token")) {
            token = ((String) request.get("token"));
        } else if (request.containsKey("tokenValue")) {
            token = ((String) request.get("tokenValue"));
