import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;

import java.time.Instant;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Collectors;

@Service
public class TokenService {

    @Autowired
    private TokenRepository tokenRepository;

    @Autowired
    private UserRepository userRepository;

    // Token expiration times in milliseconds
    private static final long ACCESS_TOKEN_LIFETIME = 10 * 60 * 1000; // 10 minutes
    private static final long REFRESH_TOKEN_LIFETIME = 24 * 60 * 60 * 1000; // 24 hours
    private static final long ONE_TIME_TOKEN_LIFETIME = 5 * 60 * 1000; // 5 minutes

    private static final String TOKEN_TYPE_ACCESS = "ACCESS_TOKEN";
    private static final String TOKEN_TYPE_REFRESH = "REFRESH_TOKEN";
    private static final String TOKEN_TYPE_ONE_TIME = "ONE_TIME_TOKEN";

    @Transactional
    public TokenResponse login(LoginRequest request) {
        // Find user by username
        UserEntity user = userRepository.findByUsername(request.getUsername())
                .orElseThrow(() -> new IllegalArgumentException("User not found"));

        // Generate unique token IDs
        String accessTokenId = generateTokenId();
        String refreshTokenId = generateTokenId();
        String oneTimeTokenId = generateTokenId();

        // Create TokenEntity instances
        TokenEntity accessToken = createTokenEntity(user, accessTokenId, 
                TOKEN_TYPE_ACCESS, Instant.now(), Instant.now().plus(ACCESS_TOKEN_LIFETIME), false, false);
        TokenEntity refreshToken = createTokenEntity(user, refreshTokenId,
                TOKEN_TYPE_REFRESH, Instant.now(), Instant.now().plus(REFRESH_TOKEN_LIFETIME), false, false);
        TokenEntity oneTimeToken = createTokenEntity(user, oneTimeTokenId,
                TOKEN_TYPE_ONE_TIME, Instant.now(), Instant.now().plus(ONE_TIME_TOKEN_LIFETIME), false, false);

        // Save tokens to database
        tokenRepository.save(accessToken);
        tokenRepository.save(refreshToken);
        tokenRepository.save(oneTimeToken);

        // Return response
        TokenResponse response = new TokenResponse();
        response.setAccessToken(accessToken.getTokenValue());
        response.setOneTimeToken(oneTimeToken.getTokenValue());

        // Set Refresh Token as HTTP-only cookie
        String refreshTokenCookieValue = "refreshToken=" + oneTimeToken.getTokenValue();
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.add("Set-Cookie", "refreshToken=" + refreshTokenCookieValue + "; HttpOnly; Max-Age=86400");

        return response;
    }

    private String generateTokenId() {
        return UUID.randomUUID().toString();
    }

    private TokenEntity createTokenEntity(UserEntity user, String tokenId, 
                                       String tokenType, Instant issuedAt, 
                                       Instant expiresAt, Boolean isRevoked, Boolean isConsumed) {
        TokenEntity token = new TokenEntity();
        token.setTokenId(tokenId);
        token.setTokenValue(UUID.randomUUID().toString() + "-" + tokenType); // Unique token value
        token.setUserId(user.getUserId());
        token.setTokenType(tokenType);
        token.setIssuedAt(issuedAt);
        token.setExpiresAt(expiresAt);
        token.setIsRevoked(isRevoked);
        token.setIsConsumed(isConsumed);
        return token;
    }

    @Transactional
    public TokenResponse renewRefreshToken(String refreshToken) {
        // Find existing refresh token by its value
        TokenEntity existingToken = tokenRepository.findByTokenValue(refreshToken)
                .orElseThrow(() -> new IllegalArgumentException("Invalid refresh token"));

        // Check if token is revoked
        if (existingToken.getIsRevoked()) {
            throw new IllegalArgumentException("Refresh token is revoked");
        }

        // Check if token is expired
        Instant now = Instant.now();
        if (now.compareTo(existingToken.getExpiresAt()) > 0) {
            throw new IllegalArgumentException("Refresh token has expired");
        }

        // Check if token is consumed (should not be for refresh tokens)
        if (existingToken.getIsConsumed()) {
            throw new IllegalArgumentException("Refresh token has been consumed");
        }

        // Perform refresh token rotation:
        // 1. Revoke current refresh token
        existingToken.setIsRevoked(true);

        // 2. Issue new refresh token
        String newRefreshTokenId = generateTokenId();
        TokenEntity newRefreshToken = createTokenEntity(
                existingToken.getUserId(), 
                newRefreshTokenId, 
                TOKEN_TYPE_REFRESH, 
                Instant.now(), 
                Instant.now().plus(REFRESH_TOKEN_LIFETIME), 
                false, 
                false
        );
        tokenRepository.save(newRefreshToken);

        // 3. Issue new access token (linked to user)
        String newAccessTokenId = generateTokenId();
        TokenEntity newAccessToken = createTokenEntity(
                existingToken.getUserId(), 
                newAccessTokenId, 
                TOKEN_TYPE_ACCESS, 
                Instant.now(), 
                Instant.now().plus(ACCESS_TOKEN_LIFETIME), 
                false, 
                false
        );
        tokenRepository.save(newAccessToken);

        // Return response with new tokens
        TokenResponse response = new TokenResponse();
        response.setAccessToken(newAccessToken.getTokenValue());
        response.setOneTimeToken(newAccessToken.getTokenValue()); // One-time token is also renewed

        // Set new refresh token as cookie
        String newRefreshTokenCookieValue = "refreshToken=" + newRefreshToken.getTokenValue();
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.add("Set-Cookie", "refreshToken=" + newRefreshTokenCookieValue + "; HttpOnly; Max-Age=86400");

        return response;
    }

    @Transactional
    public TokenResponse validateToken(String token) {
        // Find token by value
        TokenEntity token = tokenRepository.findByTokenValue(token)
                .orElseThrow(() -> new IllegalArgumentException("Invalid token"));

        // Check if token exists and not revoked
        if (token.getIsRevoked()) {
            return Map.of("valid", false, "message", "Token is revoked");
        }

        // Check if token is consumed (one-time tokens must be consumed)
        if (token.getIsConsumed()) {
            return Map.of("valid", false, "message", "Token has already been consumed");
        }

        // Check if token has expired
        Instant now = Instant.now();
        if (now.compareTo(token.getExpiresAt()) > 0) {
            return Map.of("valid", false, "message", "Token has expired");
        }

        // Valid token - mark as consumed
        token.setIsConsumed(true);
        tokenRepository.save(token);

        // Return success response
        return Map.of("valid", true, "message", "Token validated successfully");
    }

    @Transactional
    public void logout(String accessToken) {
        // Find user by accessing their tokens
        // Need to find user from token's userId
        String userId = null;

        // Extract userId from access token - it's stored in TokenEntity.userId
        // We need to find the token first
        TokenEntity token = tokenRepository.findByTokenValue(accessToken)
                .orElseThrow(() -> new IllegalArgumentException("Invalid access token"));

        userId = token.getUserId();

        // Invalidate all tokens for this user
        // Revoke all tokens belonging to this user
        List<TokenEntity> userTokens = tokenRepository.findAllByUserId(userId);

        for (TokenEntity token : userTokens) {
            // Mark all tokens as revoked
            token.setIsRevoked(true);
            // Also mark one-time tokens as consumed
            token.setIsConsumed(true);

            // Delete expired/revoked tokens from database
            if (token.getIsRevoked() || token.getIsConsumed()) {
                // Clean up - delete tokens that are expired, revoked, or consumed
                // This is done by background cleanup task
                // For now, we just mark them
            }
        }

        // Update user's tokens in database
        userRepository.save(userRepository.findById(userId).orElseThrow());
    }
