package com.auth.token.controller;

import com.auth.token.dto.LoginRequest;
import com.auth.token.dto.TokenResponse;
import com.auth.token.service.TokenService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.*;

import java.util.Map;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    @Autowired
    private TokenService tokenService;

    @Autowired
    private TokenRepository tokenRepository;

    @Autowired
    private UserRepository userRepository;

    @PostMapping("/login")
    public ResponseEntity<TokenResponse> login(@RequestBody LoginRequest request) {
        // Validate input
        if (request == null || request.getUsername() == null || request.getUsername().isEmpty() ||
            request.getPassword() == null || request.getPassword().isEmpty()) {
            return ResponseEntity.badRequest().build();
        }

        // Find user by username
        UserEntity user = userRepository.findByUsername(request.getUsername())
                .orElseThrow(() -> new IllegalArgumentException("User not found"));

        // Perform login and get tokens
        TokenResponse response = tokenService.login(request);

        // Set Refresh Token as HTTP-only cookie
        // Spec says: Cookie: refreshToken=<token>; HttpOnly; Max-Age=86400
        String refreshTokenCookieValue = "refreshToken=" + response.getOneTimeToken();
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.add("Set-Cookie", "refreshToken=" + refreshTokenCookieValue + "; HttpOnly; Max-Age=86400");

        return ResponseEntity.ok()
                .contentType(MediaType.APPLICATION_JSON)
                .body(response);
    }

    @PostMapping("/renew")
    public ResponseEntity<TokenResponse> renew(@RequestParam Map<String, String> requestMap) {
        // Get refresh token from cookie or header
        String refreshTokenCookie = requestMap.get("refreshTokenCookie");
        String refreshTokenHeader = requestMap.get("refreshTokenHeader");

        // Cookie takes precedence if present
        String refreshToken = refreshTokenCookie != null && !refreshTokenCookie.isEmpty() 
                ? refreshTokenCookie 
                : refreshTokenHeader != null && !refreshTokenHeader.isEmpty() 
                        ? refreshTokenHeader 
                        : null;

        if (refreshToken == null || refreshToken.isEmpty()) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(new TokenResponse());
        }

        // Perform token renewal
        TokenResponse renewedResponse = tokenService.renewRefreshToken(refreshToken);

        // Set new refresh token as cookie
        String newRefreshTokenCookieValue = "refreshToken=" + renewedResponse.getAccessToken();
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.add("Set-Cookie", "refreshToken=" + newRefreshTokenCookieValue + "; HttpOnly; Max-Age=86400");

        return ResponseEntity.ok()
                .contentType(MediaType.APPLICATION_JSON)
                .body(renewedResponse);
    }

    @PostMapping("/logout")
    public ResponseEntity<Map<String, Object>> logout(@RequestHeader("Authorization") String authorizationHeader) {
        // Validate access token from header
        if (authorizationHeader == null || !authorizationHeader.startsWith("Bearer ")) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(Map.of("message", "Invalid authorization header"));
        }

        String accessToken = authorizationHeader.substring(7); // Remove "Bearer " prefix

        // Find the token to get user ID
        TokenEntity token = tokenRepository.findByTokenValue(accessToken)
                .orElseThrow(() -> new IllegalArgumentException("Invalid access token"));

        String userId = token.getUserId();

        // Logout invalidates all tokens for this user
        // Revoke all tokens belonging to this user
        List<TokenEntity> userTokens = tokenRepository.findAllByUserId(userId);

        for (TokenEntity userToken : userTokens) {
            // Mark all tokens as revoked
            userToken.setIsRevoked(true);
            // Also mark one-time tokens as consumed
            userToken.setIsConsumed(true);
        }

        // Delete expired/revoked tokens from database (already done in cleanup task)

        // Return success response
        return ResponseEntity.ok(Map.of("message", "Logged out successfully"));
    }

    @PostMapping("/validate-token")
    public ResponseEntity<Map<String, Object>> validateToken(@RequestBody Map<String, Object> request) {
        String token = null;

        // Extract token from request parameter
        if (request.containsKey("token")) {
            token = ((String) request.get("token")).toString();
        } else if (request.containsKey("tokenValue")) {
            token = ((String) request.get("tokenValue")).toString();
        } else {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(Map.of("valid", false, "message", "Token parameter missing"));
        }

        // Validate token
