        // Return success response
        return ResponseEntity.ok(Map.of("message", "Logged out successfully"));
    }

    @PostMapping("/validate-token")
    public ResponseEntity<Map<String, Object>> validateToken(@RequestBody Map<String, Object> request) {
        String token = null;

        // Extract token from request parameter
        if (request.containsKey("token")) {
            token = ((String) request.get("token")).toString();
        } else if (request.containsKey("tokenValue")) {
            token = ((String) request.get("tokenValue")).toString();
        } else {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(Map.of("valid", false, "message", "Token parameter missing"));
        }

        // Validate token
        Map<String, Object> response = tokenService.validateToken(token);

        return ResponseEntity.ok(response);
    }
