package com.auth.token.service;

import com.auth.token.entity.TokenEntity;
import com.auth.token.entity.UserEntity;
import com.auth.token.dto.TokenResponse;
import com.auth.token.repository.TokenRepository;
import com.auth.token.repository.UserRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;

import javax.persistence.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Collectors;

@Service
public class TokenService {

    @Autowired
    private TokenRepository tokenRepository;

    @Autowired
    private UserRepository userRepository;

    // Token expiration times in milliseconds
    private static final long ACCESS_TOKEN_LIFETIME = 10 * 60 * 1000; // 10 minutes
    private static final long REFRESH_TOKEN_LIFETIME = 24 * 60 * 60 * 1000; // 24 hours
    private static final long ONE_TIME_TOKEN_LIFETIME = 5 * 60 * 1000; // 5 minutes

    private static final String TOKEN_TYPE_ACCESS = "ACCESS_TOKEN";
    private static final String TOKEN_TYPE_REFRESH = "REFRESH_TOKEN";
    private static final String TOKEN_TYPE_ONE_TIME = "ONE_TIME_TOKEN";

    // Scheduled cleanup task - runs every 10 seconds
    @Scheduled(fixedRate = 10000)
    @Transactional
    public void cleanupExpiredTokens() {
        // Get all tokens from database
        List<TokenEntity> allTokens = tokenRepository.findAll();

        int deletedCount = 0;

        // Iterate through all tokens and clean up invalid ones
        for (TokenEntity token : allTokens) {
            // Check if token should be deleted:
            // - Expired (expires_at is in the past)
            // - Revoked (is_revoked is true)
            // - Consumed (is_consumed is true)

            boolean shouldDelete = false;

            if (token.getIsRevoked() || token.getIsConsumed()) {
                // Already marked as revoked or consumed, delete
                tokenRepository.delete(token);
                deletedCount++;
                continue;
            }

            // Check expiration
            Instant now = Instant.now();
            if (now.isAfter(token.getExpiresAt())) {
                // Token has expired, delete
                tokenRepository.delete(token);
                deletedCount++;
            }
        }

        // Log cleanup action
        System.out.println("[CLEANUP] Deleted " + deletedCount + " tokens");
    }

    @Transactional
    public TokenResponse login(LoginRequest request) {
        // Find user by username
        UserEntity user = userRepository.findByUsername(request.getUsername())
                .orElseThrow(() -> new IllegalArgumentException("User not found"));

        // Generate unique token IDs
        String accessTokenId = generateTokenId();
        String refreshTokenId = generateTokenId();
        String oneTimeTokenId = generateTokenId();

        // Create TokenEntity instances
        TokenEntity accessToken = createTokenEntity(user, accessTokenId, 
                TOKEN_TYPE_ACCESS, Instant.now(), Instant.now().plus(ACCESS_TOKEN_LIFETIME), false, false);
        TokenEntity refreshToken = createTokenEntity(user, refreshTokenId,
                TOKEN_TYPE_REFRESH, Instant.now(), Instant.now().plus(REFRESH_TOKEN_LIFETIME), false, false);
        TokenEntity oneTimeToken = createTokenEntity(user, oneTimeTokenId,
                TOKEN_TYPE_ONE_TIME, Instant.now(), Instant.now().plus(ONE_TIME_TOKEN_LIFETIME), false, false);

        // Save tokens to database
        tokenRepository.save(accessToken);
        tokenRepository.save(refreshToken);
        tokenRepository.save(oneTimeToken);

        // Return response
        TokenResponse response = new TokenResponse();
        response.setAccessToken(accessToken.getTokenValue());
        response.setOneTimeToken(oneTimeToken.getTokenValue());

        // Set Refresh Token as HTTP-only cookie
        String refreshTokenCookieValue = "refreshToken=" + oneTimeToken.getTokenValue();
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.add("Set-Cookie", "refreshToken=" + refreshTokenCookieValue + "; HttpOnly; Max-Age=86400");

        return response;
    }

    private String generateTokenId() {
        return UUID.randomUUID().toString();
    }

    private TokenEntity createTokenEntity(UserEntity user, String tokenId, 
                                       String tokenType, Instant issuedAt, 
                                       Instant expiresAt, Boolean isRevoked, Boolean isConsumed) {
        TokenEntity token = new TokenEntity();
        token.setTokenId(tokenId);
        token.setTokenValue(UUID.randomUUID().toString() + "-" + tokenType); // Unique token value
        token.setUserId(user.getUserId());
        token.setTokenType(tokenType);
        token.setIssuedAt(issuedAt);
        token.setExpiresAt(expiresAt);
        token.setIsRevoked(isRevoked);
        token.setIsConsumed(isConsumed);
        return token;
    }

    @Transactional
    public TokenResponse renewRefreshToken(String refreshToken) {
